             // Función para cargar los productos en la página
      function loadProducts(country = 'peru') {
          // Ocultar todas las secciones de país
          document.querySelectorAll('.country-section').forEach(section => {
              section.classList.remove('active');
          });

          // Mostrar la sección del país seleccionado
          const countrySection = document.querySelector(`.country-section[data-country="${country}"]`);
          countrySection.classList.add('active');

          // Limpiar el contenido existente (excepto el encabezado)
          const existingProducts = countrySection.querySelectorAll('.category-title, .products-grid');
          existingProducts.forEach(el => el.remove());

          // Cargar productos por categoría
          for (const [category, products] of Object.entries(dxnProducts[country])) {
              const categoryTitle = document.createElement('h3');
              categoryTitle.className = 'category-title';
              categoryTitle.textContent = category;
              countrySection.appendChild(categoryTitle);

              const productsGrid = document.createElement('div');
              productsGrid.className = 'products-grid';

              products.forEach(product => {
                  const productCard = document.createElement('div');
                  productCard.className = 'product-card';

                  productCard.innerHTML = `
      <div class="product-image">
          <img src="${product.img}" alt="${product.name}">
      </div>
      <div class="product-info">
          <span class="product-category">${category}</span>
          <h3 class="product-name">${product.name}</h3>
          <p class="product-description">${product.desc}</p>
          <div class="product-details">
              <span class="product-id">${product.id || ""}</span>
          </div>
      </div>
      <div class="product-country">
          <img src="https://flagcdn.com/w320/${getCountryCode(country)}.png"
               alt="Bandera de ${country}"
               loading="lazy">
      </div>
      `;

                  productsGrid.appendChild(productCard);
              });

              countrySection.appendChild(productsGrid);
          }
      }

              // Obtener código de país para bandera
              function getCountryCode(country) {
                  const countryCodes = {
                      'peru': 'pe',
                      'bolivia': 'bo',
                      'ecuador': 'ec',
                      'colombia': 'co',
                      'argentina': 'ar',
                      'brasil': 'br',
                      'mexico': 'mx',
                      'panama': 'pa'
                  };
                  return countryCodes[country] || 'pe';
              }

              // Inicializar la página
              document.addEventListener('DOMContentLoaded', function() {

                  // Añadir event listeners a los botones de bandera
                  document.querySelectorAll('.flag-btn').forEach(button => {
                      button.addEventListener('click', function() {
                          // Quitar la clase active de todos los botones
                          document.querySelectorAll('.flag-btn').forEach(btn => {
                              btn.classList.remove('active');
                          });

                          // Añadir la clase active al botón clickeado
                          this.classList.add('active');

                          // Cargar los productos del país seleccionado
                          const country = this.dataset.country;
                          loadProducts(country);
                      });
                  });
              });
